    getLastCommand() {
        return this.lastCommand;
    }
    getLastConfidence() {
        return this.lastConfidence;
    }
    destroy() {
        this.stop();
        if (this.recognition) {
            this.recognition.onstart = null;
            this.recognition.onresult = null;
            this.recognition.onend = null;
            this.recognition.onerror = null;
            this.recognition = undefined;
        }
    }
